<script setup>
import { computed, ref } from 'vue'

const props = defineProps({ roles: { type: Array, default: () => [] }, menus: { type: Array, default: () => [] }, apiResources: { type: Array, default: () => [] } })
const emit = defineEmits(['create', 'update-permissions', 'refresh'])
const roleDialogOpen = ref(false)
const permissionDrawerOpen = ref(false)
const permissionTab = ref('menus')
const selectedRole = ref(null)
const newRole = ref({ name: '', code: '', description: '' })
const permissionDraft = ref({ menu_keys: ['workspace'], api_ids: [] })
const menuOptions = computed(() => [...props.menus].sort((left, right) => Number(left.sort) - Number(right.sort) || Number(left.ID) - Number(right.ID)))
const apiGroups = computed(() => props.apiResources.reduce((groups, item) => { ;(groups[item.group] ||= []).push(item); return groups }, {}))

function decodeMenuKeys(role) { if (Array.isArray(role?.menu_keys)) return role.menu_keys; try { const keys = JSON.parse(role?.menu_keys || '[]'); return Array.isArray(keys) ? keys : [] } catch { return [] } }
function isParentMenu(menu) { return menuOptions.value.some((item) => item.parent_key === menu.menu_key) }
function isMenuSelected(menu) { return permissionDraft.value.menu_keys.includes(menu.menu_key) }
function toggleMenu(menu, checked) {
  const selected = new Set(permissionDraft.value.menu_keys)
  if (checked) selected.add(menu.menu_key)
  else selected.delete(menu.menu_key)
  const children = menuOptions.value.filter((item) => item.parent_key === menu.menu_key)
  if (children.length) children.forEach((item) => checked ? selected.add(item.menu_key) : selected.delete(item.menu_key))
  if (checked && menu.parent_key) selected.add(menu.parent_key)
  permissionDraft.value.menu_keys = [...selected]
}
function openCreateRole() { newRole.value = { name: '', code: '', description: '' }; roleDialogOpen.value = true }
function submitRole() { emit('create', { ...newRole.value, menu_keys: ['workspace'], api_ids: [] }); roleDialogOpen.value = false }
function openPermissionDrawer(role) { selectedRole.value = role; permissionDraft.value = { menu_keys: decodeMenuKeys(role), api_ids: Array.isArray(role?.api_ids) ? role.api_ids.map(Number) : [] }; permissionTab.value = 'menus'; permissionDrawerOpen.value = true }
function configurableAPIs(items) { return items.filter((item) => !item.is_public) }
function selectAPIGroup(items, checked) { const selected = new Set(permissionDraft.value.api_ids.map(Number)); configurableAPIs(items).forEach((item) => checked ? selected.add(item.ID) : selected.delete(item.ID)); permissionDraft.value.api_ids = [...selected] }
function isAPIGroupSelected(items) { const configurable = configurableAPIs(items); const selected = new Set(permissionDraft.value.api_ids.map(Number)); return configurable.length > 0 && configurable.every((item) => selected.has(item.ID)) }
function savePermissions() { emit('update-permissions', { roleID: selectedRole.value.ID, ...permissionDraft.value, api_ids: permissionDraft.value.api_ids.map(Number) }); permissionDrawerOpen.value = false }
</script>

<template>
  <section class="panel role-panel"><div class="panel-heading role-heading"><div class="heading-actions"><button class="secondary" type="button" @click="openCreateRole">＋ 新增角色</button><button class="text-button" type="button" @click="$emit('refresh')">刷新</button></div></div><div class="table-wrap role-table"><table><thead><tr><th>角色名称</th><th>角色代码</th><th>说明</th><th>类型</th><th class="actions-column">操作</th></tr></thead><tbody><tr v-for="role in roles" :key="role.ID"><td><strong>{{ role.name }}</strong></td><td><code>{{ role.code }}</code></td><td>{{ role.description || '—' }}</td><td><span :class="['role-type', { builtin: role.is_builtin }]">{{ role.is_builtin ? '内置角色' : '自定义角色' }}</span></td><td class="role-actions"><button v-if="role.code !== 'owner'" type="button" @click="openPermissionDrawer(role)">⚙ 配置权限</button><span v-else class="muted">系统自动维护</span></td></tr><tr v-if="!roles.length"><td colspan="5" class="muted">暂无角色数据。</td></tr></tbody></table></div></section>

  <div v-if="roleDialogOpen" class="modal-backdrop" @click.self="roleDialogOpen = false"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="create-role-title"><div class="panel-heading"><div><p>CUSTOM ROLE</p><h2 id="create-role-title">新增角色</h2></div><button class="icon-button" type="button" aria-label="关闭" @click="roleDialogOpen = false">×</button></div><p class="helper">先创建角色，再在“配置权限”中精确设置菜单和 API；新角色默认可访问工作台。</p><form class="form-stack" @submit.prevent="submitRole"><label>角色名称<input v-model="newRole.name" required maxlength="128" placeholder="例如：归档管理员" /></label><label>角色代码<input v-model="newRole.code" required maxlength="64" placeholder="例如：archive-admin" /></label><label>说明<input v-model="newRole.description" maxlength="255" placeholder="角色用途（可选）" /></label><div class="modal-actions"><button class="ghost" type="button" @click="roleDialogOpen = false">取消</button><button class="primary" type="submit">创建角色</button></div></form></section></div>

  <div v-if="permissionDrawerOpen" class="drawer-backdrop" @click.self="permissionDrawerOpen = false"><aside class="permission-drawer" role="dialog" aria-modal="true" aria-labelledby="permission-title"><div class="drawer-header"><div><p>ROLE CONFIGURATION</p><h2 id="permission-title">{{ selectedRole?.name }} · 权限配置</h2><span>{{ selectedRole?.code }}</span></div><button class="icon-button" type="button" aria-label="关闭" @click="permissionDrawerOpen = false">×</button></div><div class="drawer-tabs" role="tablist"><button :class="{ active: permissionTab === 'menus' }" type="button" @click="permissionTab = 'menus'">角色菜单</button><button :class="{ active: permissionTab === 'apis' }" type="button" @click="permissionTab = 'apis'">角色 API</button></div><div v-if="permissionTab === 'menus'" class="permission-content"><p class="helper">菜单由“菜单配置”统一维护。勾选父菜单会一并选择直属子菜单；选择子菜单会自动保留父菜单。</p><label v-for="menu in menuOptions" :key="menu.ID || menu.menu_key" :class="['permission-row', { parent: isParentMenu(menu), child: menu.parent_key }]"><input type="checkbox" :checked="isMenuSelected(menu)" @change="toggleMenu(menu, $event.target.checked)" /><span><strong>{{ menu.name }}</strong><small>{{ menu.description || (isParentMenu(menu) ? '前端导航父菜单' : '前端导航菜单') }}</small></span></label><p v-if="!menuOptions.length" class="muted">菜单目录尚未配置。</p></div><div v-else class="permission-content"><p class="helper">每条 API 都有用途说明。勾选并保存后，Casbin 才会授予该角色访问权限。</p><section v-for="(items, group) in apiGroups" :key="group" class="permission-api-group"><label class="group-toggle"><input type="checkbox" :disabled="!configurableAPIs(items).length" :checked="isAPIGroupSelected(items)" @change="selectAPIGroup(items, $event.target.checked)" /><strong>{{ group }}</strong><small>{{ items.length }} 个接口</small></label><label v-for="api in items" :key="api.ID" class="api-row"><input v-model="permissionDraft.api_ids" type="checkbox" :value="api.ID" :disabled="api.is_public" /><code>{{ api.method }}</code><span><strong>{{ api.path }}</strong><small>{{ api.is_public ? '系统基础接口，不参与角色授权。' : (api.description || '系统接口。') }}</small></span></label></section><p v-if="!Object.keys(apiGroups).length" class="muted">接口目录正在加载，请刷新页面后再试。</p></div><footer class="drawer-footer"><button class="ghost" type="button" @click="permissionDrawerOpen = false">取消</button><button class="primary" type="button" @click="savePermissions">保存权限</button></footer></aside></div>
</template>

<style scoped>
.panel{padding:24px;border:1px solid #dce5df;border-radius:14px;background:#fff;box-shadow:0 8px 20px rgba(30,58,44,.04)}.role-panel{min-height:420px}.panel-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:22px}.panel-heading p,.drawer-header p{margin:0;color:#5c796c;font-size:11px;font-weight:800;letter-spacing:.12em}.panel-heading h2{margin:5px 0 0;font-size:21px}.role-heading{justify-content:flex-start;margin-bottom:0}.heading-actions{display:flex;align-items:center;gap:14px}.helper{margin:-4px 0 18px;color:#65766d;font-size:13px;line-height:1.65}.secondary,.ghost{min-height:38px;padding:0 14px;border:1px solid #b9d2c5;border-radius:7px;color:#1b6854;background:#f5faf6;font-weight:700}.secondary{border-color:#1e6956;color:#fff;background:#1e6956}.text-button{border:0;color:#1b6854;background:none;font-weight:700}.table-wrap{overflow-x:auto}.role-table{margin-top:18px;border:1px solid #e1e9e3;border-radius:9px}.role-table table{width:100%;min-width:680px;border-collapse:collapse;font-size:13px}.role-table th,.role-table td{height:54px;padding:12px 10px;border-bottom:1px solid #e8eeea;text-align:left;white-space:nowrap}.role-table th{color:#61736a;font-weight:700}.actions-column{width:160px}.role-actions button{border:0;color:#176dcb;background:transparent;font-weight:650}.role-type{display:inline-block;padding:4px 8px;border-radius:999px;color:#5e7067;background:#edf2ee;font-size:12px}.role-type.builtin{color:#28614c;background:#e5f4e9}.muted{color:#7a8981}.modal-backdrop,.drawer-backdrop{position:fixed;z-index:30;inset:0;background:rgba(14,28,22,.46)}.modal-backdrop{display:grid;place-items:center;padding:20px}.modal-card{width:min(480px,100%);padding:26px;border-radius:14px;background:#fff;box-shadow:0 24px 72px rgba(0,0,0,.22)}.form-stack{display:grid;gap:16px}.form-stack label{display:grid;gap:7px;color:#4d6258;font-size:13px;font-weight:650}.form-stack input{width:100%;min-height:42px;padding:0 12px;border:1px solid #cfdcd3;border-radius:8px;color:#192820;background:#fff}.modal-actions,.drawer-footer{display:flex;justify-content:flex-end;gap:10px}.primary{min-height:42px;padding:0 16px;border:0;border-radius:8px;color:#fff;background:#1e6956;font-weight:700}.icon-button{display:grid;width:32px;height:32px;place-items:center;border:0;border-radius:7px;color:#52645a;background:#eff3f0;font-size:23px;line-height:1}.drawer-backdrop{display:flex;justify-content:flex-end}.permission-drawer{display:flex;width:min(620px,100vw);height:100%;flex-direction:column;background:#fff;box-shadow:-12px 0 34px rgba(0,0,0,.16)}.drawer-header{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;padding:28px 30px 18px;border-bottom:1px solid #e4ebe6}.drawer-header h2{margin:6px 0 4px;font-size:23px}.drawer-header span{color:#658176;font-size:12px}.drawer-tabs{display:flex;padding:0 30px;border-bottom:1px solid #e4ebe6}.drawer-tabs button{padding:14px 16px 12px;border:0;border-bottom:2px solid transparent;color:#687a70;background:transparent;font-weight:700}.drawer-tabs button.active{border-color:#1e6956;color:#1e6956}.permission-content{flex:1;overflow:auto;padding:24px 30px}.permission-content .helper{margin:0 0 18px}.permission-row{display:flex;align-items:center;gap:12px;padding:14px 6px;border-bottom:1px solid #edf1ee}.permission-row.parent{margin-top:8px;border:1px solid #dce8df;border-radius:8px;background:#f6faf7;font-weight:700}.permission-row.child{margin-left:14px;padding-left:14px;border-left:2px solid #dce8df}.permission-row input,.group-toggle input,.api-row input{width:16px;height:16px;accent-color:#1e6956}.permission-row span{display:grid;gap:3px}.permission-row small{color:#74857c;font-size:12px}.permission-api-group{margin-bottom:18px;border:1px solid #e0e8e2;border-radius:8px}.group-toggle{display:flex;align-items:center;gap:9px;padding:12px;border-bottom:1px solid #e6ece8;background:#f7faf8}.group-toggle small{margin-left:auto;color:#75877d;font-size:12px}.api-row{display:flex;align-items:center;gap:9px;padding:9px 12px;border-bottom:1px solid #eff3f0;font-size:12px}.api-row:last-child{border-bottom:0}.api-row code{min-width:42px;color:#2b765f;font-weight:700}.api-row span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#53665b}.drawer-footer{padding:16px 30px;border-top:1px solid #e4ebe6;background:#fafcfb}@media(max-width:600px){.permission-drawer{width:100%}.drawer-header,.permission-content,.drawer-footer{padding-left:18px;padding-right:18px}.drawer-tabs{padding:0 18px}.heading-actions{gap:8px}.role-heading{align-items:flex-start;flex-direction:column}}
</style>

